package com.connecta.backend.support;

import com.connecta.backend.user.domain.Role;
import com.connecta.backend.user.domain.User;
import java.lang.reflect.Field;
import java.util.UUID;

/** Builds users for tests. Ids are normally generated by the database, so they are set directly here. */
public final class TestUsers {

    private TestUsers() {
    }

    public static User user(String email, String... roleNames) {
        User user = new User(email, "hash", "Test User");
        for (String name : roleNames) {
            user.addRole(new Role(name));
        }
        set(user, "id", UUID.randomUUID());
        return user;
    }

    public static void set(Object target, String field, Object value) {
        try {
            Field f = target.getClass().getDeclaredField(field);
            f.setAccessible(true);
            f.set(target, value);
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException(e);
        }
    }
}
